package ultra.downloads;
import java.util.*;
/** Renderer-independent, reserved-id-only row substitution before native presentation. */
public final class RadioWire {
 static boolean contains(byte[] b,byte[] needle){outer:for(int i=0;i<=b.length-needle.length;i++){for(int j=0;j<needle.length;j++)if(b[i+j]!=needle[j])continue outer;return true;}return false;}
 public static volatile String status="not-called";
 static final byte[] RADIO_ID=HeaderCommands.text("FEmusic_ultra_radio");
 static final String ART="android.resource://app.rvx.android.apps.youtube.musiy/"+0x7f080933;
 static final class Result{byte[] bytes,clone;boolean command,changed;Result(byte[] b){bytes=b;}}
 static byte[] art(byte[] b,int d){if(d>48)return b;String value=new String(b,java.nio.charset.StandardCharsets.UTF_8);if(value.startsWith("https://")&&(value.contains("ytimg.com/")||value.contains("googleusercontent.com/")||value.contains("gstatic.com/")||value.contains("ggpht.com/")))return HeaderCommands.text(ART);try{List<HeaderCommands.F> fs=HeaderCommands.fields(b);boolean changed=false;for(HeaderCommands.F f:fs)if(f.w==2){byte[] n=art(f.value,d+1);if(n!=f.value){f.raw=HeaderCommands.field(f.n,n);changed=true;}}return changed?HeaderCommands.encode(fs):b;}catch(Exception e){return b;}}
 static byte[] noMenu(byte[] b,int d){if(d>48)return b;try{List<HeaderCommands.F> fs=HeaderCommands.fields(b);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();boolean changed=false;for(HeaderCommands.F f:fs){if(f.n==0x3f5caaa&&f.w==2){changed=true;continue;}byte[] raw=f.raw;if(f.w==2){byte[] n=noMenu(f.value,d+1);if(n!=f.value){changed=true;if(n.length==0)continue;raw=HeaderCommands.field(f.n,n);}}out.write(raw,0,raw.length);}return changed?out.toByteArray():b;}catch(Exception e){return b;}}
 static Result walk(byte[] b,int browseExtension,byte[] watch,int d,int[] budget){Result result=new Result(b);if(d>48||--budget[0]<0)return result;List<HeaderCommands.F> fs;try{fs=HeaderCommands.fields(b);}catch(Exception e){return result;}
  for(HeaderCommands.F f:fs)if(f.w==2&&f.n==browseExtension){try{byte[] id=HeaderCommands.get(HeaderCommands.fields(f.value),2);if(Arrays.equals(id,HeaderCommands.text("VLLM"))||Arrays.equals(id,HeaderCommands.text("LM")))result.command=true;}catch(Exception ignored){}}
  boolean modified=false,pending=false;java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream(),copy=new java.io.ByteArrayOutputStream();
  for(HeaderCommands.F f:fs){byte[] raw=f.raw,extra=null;if(f.w==2){Result child=walk(f.value,browseExtension,watch,d+1,budget);result.command|=child.command;result.changed|=child.changed;if(child.bytes!=f.value){raw=HeaderCommands.field(f.n,child.bytes);modified=true;}if(child.clone!=null){int same=0;for(HeaderCommands.F x:fs)if(x.n==f.n&&x.w==2)same++;if(same>1){extra=HeaderCommands.field(f.n,child.clone);result.changed=true;modified=true;}else{copy.write(HeaderCommands.field(f.n,child.clone),0,HeaderCommands.field(f.n,child.clone).length);pending=true;}}else copy.write(raw,0,raw.length);}else copy.write(raw,0,raw.length);if(extra!=null)out.write(extra,0,extra.length);out.write(raw,0,raw.length);}
  if(modified)result.bytes=out.toByteArray();if(pending)result.clone=copy.toByteArray();
  if(!result.changed&&result.clone==null&&result.command&&(contains(b,HeaderCommands.text("Liked music"))||contains(b,HeaderCommands.text("Liked Music")))&&contains(b,HeaderCommands.text("Auto playlist"))){byte[] n=commands(b,browseExtension,watch,0,new int[]{24000});n=HeaderCommands.labels(n,"Liked music","Radio",0);n=HeaderCommands.labels(n,"Liked Music","Radio",0);n=HeaderCommands.labels(n,"Auto playlist","Based on your last played song",0);result.clone=noMenu(art(n,0),0);}
  return result;
 }
 static byte[] commands(byte[] b,int extension,byte[] watch,int d,int[] budget){if(d>48||--budget[0]<0)return b;List<HeaderCommands.F> fs;try{fs=HeaderCommands.fields(b);}catch(Exception e){return b;}
  for(HeaderCommands.F f:fs)if(f.n==extension&&f.w==2){try{byte[] id=HeaderCommands.get(HeaderCommands.fields(f.value),2);if(Arrays.equals(id,HeaderCommands.text("VLLM"))||Arrays.equals(id,HeaderCommands.text("LM"))){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();for(HeaderCommands.F x:fs)if(x!=f)out.write(x.raw,0,x.raw.length);out.write(watch,0,watch.length);return out.toByteArray();}}catch(Exception ignored){}}
  boolean changed=false;for(HeaderCommands.F f:fs)if(f.w==2){byte[] n=commands(f.value,extension,watch,d+1,budget);if(n!=f.value){f.raw=HeaderCommands.field(f.n,n);changed=true;}}return changed?HeaderCommands.encode(fs):b;
 }
 public static byte[] transform(byte[] response,int browseExtension,byte[] watch){if(response==null||response.length>HeaderCommands.MAX||watch==null)return response;status="input-"+response.length+"-liked-"+(contains(response,HeaderCommands.text("Liked music"))||contains(response,HeaderCommands.text("Liked Music")))+"-existing-"+contains(response,RADIO_ID);if(contains(response,RADIO_ID))return response;int[] budget={180000};try{Result r=walk(response,browseExtension,watch,0,budget);status+="-command-"+r.command+"-inserted-"+r.changed+"-pending-"+(r.clone!=null)+"-remaining-"+budget[0];return budget[0]>=0?r.bytes:response;}catch(Throwable e){return response;}}
}
